sys_script_include.script:
var SendSMSviaInteraction = Class.create();
SendSMSviaInteraction.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    executeSmsSubflow: function() {
        gs.info('[SMS SERVER LOG] Initializing SMS subflow handoff via SendSMSviaInteraction.');

        try {
            var interactionId = this.getParameter('sysparm_interaction');
            var reasonMessage = this.getParameter('sysparm_reason');
            var smsText       = this.getParameter('sysparm_message');

            gs.info('[SMS SERVER LOG] Parameters verified -> Interaction: ' + interactionId);

            // Fetch the Interaction GlideRecord to pass as a reference object
            var interactionGr = new GlideRecord('interaction');
            if (!interactionGr.get(interactionId)) {
                return JSON.stringify({ status: 'error', message: 'Could not find a valid Interaction record with the provided Sys ID.' });
            }

            var inputs = {};
            inputs['interaction_sys_id'] = interactionGr; 
            inputs['reason_for_message'] = reasonMessage;  
            inputs['message_to_send']    = smsText;        

            gs.info('[SMS SERVER LOG] Triggering Flow Runner Engine for: x_snc_pab_ee_tkit.send_sms_notification_int_eng');

            var result = sn_fd.FlowAPI.getRunner()
                .subflow('x_snc_pab_ee_tkit.send_sms_notification_int_eng')
                .inForeground()
                .withInputs(inputs)
                .run();

            var outputs = result.getOutputs();
            var sms_message_stats = outputs['sms_message_stats'] || '';

            gs.info('[SMS SERVER LOG] Subflow completed. Output status: ' + sms_message_stats);

            return JSON.stringify({ 
                status: 'success', 
                notes: sms_message_stats 
            });

        } catch (ex) {
            var message = ex.getMessage ? ex.getHTMLValue() : ex.message;
            gs.error('[SMS SERVER ERROR] Fatal SMS subflow exception: ' + message);
            return JSON.stringify({ status: 'error', message: message });
        }
    },

    type: 'SendSMSviaInteraction'
});
